(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   地质剖面遥感解译 · 示范脚本（整页模式，运行在沙箱 iframe 里）\n   ---------------------------------------------------------\n   三屏：\n   屏 1  语义分割：逐像素判别岩性类别（概率图 + argmax）\n   屏 2  构造线提取：从概率图里检测断层/褶皱线要素\n   屏 3  后处理矢量化：连通域 + 剔除碎斑 + 边界平滑 → 矢量图层\n   所有计算都在浏览器里完成，纯前端。\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* =====================================================\n     纯模型层（Node 可 require 做单测；浏览器里继续往下走）\n     ===================================================== */\n  var Model = (function () {\n\n    function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n    /* 固定种子随机数 */\n    function mulberry32(a) {\n      return function () {\n        a |= 0; a = a + 0x6D2B79F5 | 0;\n        var t = Math.imul(a ^ a >>> 15, 1 | a);\n        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    /* -----------------------------------------------------\n       屏 1 · 合成岩性栅格\n       生成一个 W×H 的「岩性标签图」，由若干多边形岩性体 + 噪声构成。\n       返回 { label: IntArray, conf: FloatArray }\n       rock: 岩性类别数；seed 控制布局\n       ----------------------------------------------------- */\n    var ROCK_NAMES = ['背景', '灰岩', '砂岩', '泥岩', '火山岩', '白云岩', '页岩', '砾岩', '蚀变带'];\n    var ROCK_COLORS = ['#e8e4d8', '#cbbf9a', '#e0c88a', '#a8bfd4', '#9b86a8', '#b9ceb4', '#8aa77f', '#d0a3a3', '#e0a878'];\n\n    function genRockGrid(W, H, rocks, seed) {\n      var rnd = mulberry32(seed || 20261102);\n      var label = new Int32Array(W * H), conf = new Float64Array(W * H);\n      /* 几个随机岩性体（椭圆/多边形近似） */\n      var bodies = [];\n      var nb = Math.max(4, rocks - 1);\n      for (var i = 0; i < nb; i++) {\n        bodies.push({\n          cx: rnd() * W, cy: rnd() * H,\n          rx: 30 + rnd() * 90, ry: 24 + rnd() * 70,\n          rot: rnd() * Math.PI,\n          rock: 1 + Math.floor(rnd() * (rocks - 1)),\n          conf: 0.55 + rnd() * 0.4\n        });\n      }\n      /* 一条断层线（斜线），用于构造线演示 */\n      var fx = W * 0.28, fy = H * 0.3, fx2 = W * 0.72, fy2 = H * 0.78;\n      var x, y, k;\n      for (y = 0; y < H; y++) {\n        for (x = 0; x < W; x++) {\n          var c = -1, bestD = 1e9;\n          for (k = 0; k < bodies.length; k++) {\n            var b = bodies[k];\n            var dx = (x - b.cx) * Math.cos(-b.rot) - (y - b.cy) * Math.sin(-b.rot);\n            var dy = (x - b.cx) * Math.sin(-b.rot) + (y - b.cy) * Math.cos(-b.rot);\n            var d = (dx * dx) / (b.rx * b.rx) + (dy * dy) / (b.ry * b.ry);\n            if (d < bestD) { bestD = d; c = k; }\n          }\n          if (c < 0) { label[y * W + x] = 0; conf[y * W + x] = 0.4 + rnd() * 0.2; }\n          else {\n            label[y * W + x] = bodies[c].rock;\n            conf[y * W + x] = clamp(bodies[c].conf + (rnd() + rnd() - 1) * 0.12, 0.2, 0.98);\n          }\n        }\n      }\n      /* 叠加断层线附近轻微扰动，模拟构造带 */\n      for (y = 0; y < H; y++) {\n        for (x = 0; x < W; x++) {\n          var px = fx + (fx2 - fx) * (x / W), py = fy + (fy2 - fy) * (x / W);\n          var dd = Math.sqrt((x - px) * (x - px) + (y - py) * (y - py));\n          if (dd < 4) conf[y * W + x] = clamp(conf[y * W + x] - 0.25, 0.1, 0.9);\n        }\n      }\n      return { W: W, H: H, label: label, conf: conf, bodies: bodies, fault: { x1: fx, y1: fy, x2: fx2, y2: fy2 } };\n    }\n\n    /* -----------------------------------------------------\n       屏 1 · 语义分割「模型」\n       用一个 3×3 邻域加权 + 置信度叠加模拟 U-Net 输出概率图。\n       weight 越高，边界越贴近真值（模拟训练充分）。\n       返回 { prob: FloatArray(每个像素各岩性的概率), seg: IntArray(argmax) }\n       ----------------------------------------------------- */\n    function semanticSeg(grid, rocks, weight, noise) {\n      var W = grid.W, H = grid.H;\n      var n = W * H;\n      var prob = new Float64Array(n * rocks); // 摊平：pixel-major\n      var seg = new Int32Array(n);\n      var rnd = mulberry32(20261103);\n      for (var y = 0; y < H; y++) {\n        for (var x = 0; x < W; x++) {\n          var idx = y * W + x;\n          /* 邻域一致性：与 8 邻域同标签的占比 */\n          var same = 0, tot = 0;\n          for (var dy = -1; dy <= 1; dy++) {\n            for (var dx = -1; dx <= 1; dx++) {\n              var xx = x + dx, yy = y + dy;\n              if (xx < 0 || yy < 0 || xx >= W || yy >= H) continue;\n              tot++;\n              if (grid.label[yy * W + xx] === grid.label[idx]) same++;\n            }\n          }\n          var confBase = grid.conf[idx] * (0.5 + 0.5 * (same / tot));\n          /* weight 越高 → 正确类概率越高、误判越少（模拟训练充分程度）。\n             低 weight 时正确类概率低、竞争类份额高，出现明显混淆。 */\n          var correctP = clamp(0.15 + 0.55 * weight * confBase, 0.10, 0.97);\n          var rivalShare = clamp(0.58 - weight * 0.38, 0.02, 0.6) * (1 - correctP);\n          var gt = grid.label[idx];\n          var best = 0, bestP = -1;\n          /* 随机挑一个\"竞争类\"：weight 低时更容易抢过正确类 */\n          var rival = 1 + Math.floor(rnd() * (rocks - 1));\n          for (var r = 0; r < rocks; r++) {\n            var p;\n            if (r === gt) {\n              p = correctP + (rnd() + rnd() - 1) * 0.04;\n            } else if (r === rival && rival !== gt) {\n              p = rivalShare + (rnd() + rnd() - 1) * 0.03;\n            } else {\n              p = Math.max(0.001, (1 - correctP - (rival !== gt ? rivalShare : 0)) / (rocks - (rival !== gt ? 2 : 1)));\n            }\n            p = clamp(p, 0.001, 0.999);\n            prob[idx * rocks + r] = p;\n            if (p > bestP) { bestP = p; best = r; }\n          }\n          seg[idx] = best;\n        }\n      }\n      return { prob: prob, seg: seg, rocks: rocks };\n    }\n\n    /* -----------------------------------------------------\n       屏 1 · 分割评估\n       与真值标签逐像素对比：整体准确率 + 每类 IoU。\n       ----------------------------------------------------- */\n    function segEval(grid, seg, rocks) {\n      var n = grid.W * grid.H, i, r;\n      var acc = 0;\n      /* 正确 IoU：interM = 交集计数，uniM = 真值计数 + 预测计数（交集计两次） */\n      var interM = new Float64Array(rocks), uniM = new Float64Array(rocks);\n      for (i = 0; i < n; i++) {\n        var gt = grid.label[i], pd = seg[i];\n        if (gt === pd) { acc++; interM[gt]++; }\n        uniM[gt]++;\n        uniM[pd]++;\n      }\n      acc /= n;\n      var iou = [];\n      for (r = 0; r < rocks; r++) {\n        var union = uniM[r] - interM[r];\n        iou[r] = union > 0 ? interM[r] / union : (interM[r] ? 1 : 0);\n      }\n      return { acc: acc, iou: iou };\n    }\n\n    /* -----------------------------------------------------\n       屏 2 · 构造线提取\n       从概率图/梯度图检测线状构造：用 Sobel 梯度幅值 + 阈值，\n       再做非极大抑制，得到「构造线像素」。返回可画成折线的点列。\n       ----------------------------------------------------- */\n    function detectFault(grid, thr) {\n      var W = grid.W, H = grid.H;\n      var grad = new Float64Array(W * H);\n      var rnd = mulberry32(20261104);\n      var i, y, x;\n      /* 简化梯度：对每个像素，统计其与邻居标签不同导致的\"边界响应\" */\n      for (y = 0; y < H; y++) {\n        for (x = 0; x < W; x++) {\n          var idx = y * W + x;\n          var g = 0, cnt = 0;\n          for (var dy = -1; dy <= 1; dy++) {\n            for (var dx = -1; dx <= 1; dx++) {\n              var xx = x + dx, yy = y + dy;\n              if (xx < 0 || yy < 0 || xx >= W || yy >= H) continue;\n              cnt++;\n              if (grid.label[yy * W + xx] !== grid.label[idx]) g++;\n            }\n          }\n          /* 加入与断层线的距离响应，模拟构造带梯度 */\n          var fx = grid.fault.x1 + (grid.fault.x2 - grid.fault.x1) * (x / W);\n          var fy = grid.fault.y1 + (grid.fault.y2 - grid.fault.y1) * (x / W);\n          var dd = Math.sqrt((x - fx) * (x - fx) + (y - fy) * (y - fy));\n          g += dd < 3 ? 3.2 : (dd < 6 ? 1.2 : 0);\n          grad[idx] = (g / cnt) * (1 + rnd() * 0.2);\n        }\n      }\n      /* 阈值 → 线像素 */\n      var pts = [];\n      var lineMask = new Uint8Array(W * H);\n      for (y = 0; y < H; y++) {\n        for (x = 0; x < W; x++) {\n          var idx2 = y * W + x;\n          if (grad[idx2] > thr) {\n            lineMask[idx2] = 1;\n            pts.push({ x: x, y: y, g: grad[idx2] });\n          }\n        }\n      }\n      return { grad: grad, pts: pts, lineMask: lineMask, thr: thr };\n    }\n\n    /* -----------------------------------------------------\n       屏 3 · 后处理矢量化\n       connected components on 分割图 → 剔除小面积碎斑 → 边界点序列\n       返回 { comps: [{id,rock,size,pts:[]}], kept }\n       ----------------------------------------------------- */\n    function vectorize(grid, seg, rocks, minArea) {\n      var W = grid.W, H = grid.H, n = W * H;\n      var compId = new Int32Array(n).fill(-1);\n      var sizes = [], rocksOf = [], comps = [];\n      var id = 0, i, x, y;\n      /* BFS 连通域（4 邻域） */\n      var stack = [];\n      for (i = 0; i < n; i++) {\n        if (compId[i] >= 0) continue;\n        var rock = seg[i];\n        var ccid = id++;\n        compId[i] = ccid;\n        stack.push(i);\n        var cnt = 0;\n        var pts = [];\n        while (stack.length) {\n          var cur = stack.pop();\n          cnt++;\n          var cx = cur % W, cy = (cur / W) | 0;\n          pts.push([cx, cy]);\n          var neigh = [[1, 0], [-1, 0], [0, 1], [0, -1]];\n          for (var ni = 0; ni < 4; ni++) {\n            var nx = cx + neigh[ni][0], ny = cy + neigh[ni][1];\n            if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue;\n            var nidx = ny * W + nx;\n            if (compId[nidx] < 0 && seg[nidx] === rock) {\n              compId[nidx] = ccid;\n              stack.push(nidx);\n            }\n          }\n        }\n        sizes.push(cnt); rocksOf.push(rock); comps.push({ id: ccid, rock: rock, size: cnt, pts: pts });\n      }\n      /* 剔除碎斑：size < minArea 的合并到背景 */\n      var segClean = new Int32Array(n);\n      for (i = 0; i < n; i++) {\n        var cid = compId[i];\n        segClean[i] = (sizes[cid] < minArea) ? 0 : seg[i];\n      }\n      /* 保留的连通域边界 */\n      var kept = [];\n      for (var c = 0; c < comps.length; c++) {\n        if (sizes[c] >= minArea) kept.push(comps[c]);\n      }\n      return { compId: compId, sizes: sizes, rocksOf: rocksOf, segClean: segClean, kept: kept, minArea: minArea };\n    }\n\n    return {\n      clamp: clamp, mulberry32: mulberry32,\n      ROCK_NAMES: ROCK_NAMES, ROCK_COLORS: ROCK_COLORS,\n      genRockGrid: genRockGrid, semanticSeg: semanticSeg, segEval: segEval,\n      detectFault: detectFault, vectorize: vectorize\n    };\n  })();\n\n  /* Node 单测入口 */\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = Model;\n    return;\n  }\n\n  /* =====================================================\n     浏览器接线（沙箱 iframe 内执行）\n     ===================================================== */\n  var doc = document;\n  var $ = function (id) { return doc.getElementById(id); };\n  var M = Model;\n\n  /* 全局 UI 状态 */\n  var segState = { rocks: 5, weight: 0.5, noise: 0.15 };\n  var faultThr = 0.6;\n  var vecState = { minArea: 18 };\n\n  /* 桥接：给算法解剖动画用同一份真代码 */\n  global.RemoteBridge = {\n    M: M,\n    genRockGrid: M.genRockGrid, semanticSeg: M.semanticSeg, segEval: M.segEval,\n    detectFault: M.detectFault, vectorize: M.vectorize,\n    live: function () {\n      return { rocks: segState.rocks, weight: segState.weight, noise: segState.noise, thr: faultThr, minArea: vecState.minArea };\n    }\n  };\n\n  function num(v, d) { return v.toFixed(d == null ? 1 : d); }\n  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n  /* ---------- 屏 1 渲染：语义分割 ---------- */\n  var grid1 = M.genRockGrid(64, 48, segState.rocks, 20261102);\n  var seg1 = M.semanticSeg(grid1, segState.rocks, segState.weight, segState.noise);\n\n  function renderSeg() {\n    var rocks = segState.rocks;\n    grid1 = M.genRockGrid(64, 48, rocks, 20261102);\n    seg1 = M.semanticSeg(grid1, rocks, segState.weight, segState.noise);\n    var ev = M.segEval(grid1, seg1.seg, rocks);\n\n    /* 原图（真值标签着色） */\n    var sTrue = '';\n    for (var y = 0; y < 48; y++) {\n      for (var x = 0; x < 64; x++) {\n        var r = grid1.label[y * 64 + x];\n        sTrue += '<rect x=\"' + (x * 8) + '\" y=\"' + (y * 8) + '\" width=\"8\" height=\"8\" fill=\"' + M.ROCK_COLORS[r] + '\"/>';\n      }\n    }\n    $('segTrue').innerHTML = sTrue;\n\n    /* 预测结果（argmax 着色） */\n    var sPred = '';\n    for (var y2 = 0; y2 < 48; y2++) {\n      for (var x2 = 0; x2 < 64; x2++) {\n        var r2 = seg1.seg[y2 * 64 + x2];\n        sPred += '<rect x=\"' + (x2 * 8) + '\" y=\"' + (y2 * 8) + '\" width=\"8\" height=\"8\" fill=\"' + M.ROCK_COLORS[r2] + '\"/>';\n      }\n    }\n    $('segPred').innerHTML = sPred;\n\n    /* 概率图（当前像素集中显示为概率条） */\n    var sProb = '';\n    for (var py = 0; py < 48; py += 2) {\n      for (var px = 0; px < 64; px += 2) {\n        var idx = py * 64 + px;\n        var gt = grid1.label[idx];\n        var p = seg1.prob[idx * rocks + gt];\n        var g = Math.round(255 * p);\n        var color = 'rgb(' + (255 - g) + ',' + g + ',' + (220 - g * 0.6) + ')';\n        sProb += '<rect x=\"' + (px * 8) + '\" y=\"' + (py * 8) + '\" width=\"16\" height=\"16\" fill=\"' + color + '\"/>';\n      }\n    }\n    $('segProb').innerHTML = sProb;\n\n    /* 结果读数 */\n    $('roAcc').textContent = num(ev.acc * 100, 1) + '%';\n    var iouTxt = [];\n    for (var r3 = 1; r3 < rocks; r3++) {\n      iouTxt.push(M.ROCK_NAMES[r3] + ' ' + num(ev.iou[r3] * 100, 0) + '%');\n    }\n    $('roIou').textContent = iouTxt.join(' · ');\n    /* 图例 */\n    var legend = '';\n    for (var r4 = 0; r4 < rocks; r4++) {\n      legend += '<span class=\"lg\"><i style=\"background:' + M.ROCK_COLORS[r4] + '\"><\/i>' + M.ROCK_NAMES[r4] + '<\/span>';\n    }\n    $('segLegend').innerHTML = legend;\n  }\n\n  /* ---------- 屏 2 渲染：构造线提取 ---------- */\n  function renderFault() {\n    var det = M.detectFault(grid1, faultThr);\n    var W = 64, H = 48;\n    /* 梯度热图（背景） */\n    var s = '';\n    var maxG = 1.2;\n    for (var y = 0; y < H; y += 2) {\n      for (var x = 0; x < W; x += 2) {\n        var g = det.grad[y * W + x];\n        var t = clamp(g / maxG, 0, 1);\n        var r = Math.round(255 * t), gr = Math.round(255 * (1 - t));\n        s += '<rect x=\"' + (x * 8) + '\" y=\"' + (y * 8) + '\" width=\"16\" height=\"16\" fill=\"rgb(' + r + ',' + gr + ',150)\"/>';\n      }\n    }\n    /* 检出线像素 */\n    for (var yi = 0; yi < det.pts.length; yi++) {\n      var p = det.pts[yi];\n      s += '<rect x=\"' + (p.x * 8 + 2) + '\" y=\"' + (p.y * 8 + 2) + '\" width=\"4\" height=\"4\" fill=\"#b05a51\"/>';\n    }\n    /* 真实断层线参考 */\n    s += '<line x1=\"' + grid1.fault.x1 * 8 + '\" y1=\"' + grid1.fault.y1 * 8 + '\" x2=\"' + grid1.fault.x2 * 8 + '\" y2=\"' + grid1.fault.y2 * 8 + '\" stroke=\"#2f7d6b\" stroke-width=\"2\" stroke-dasharray=\"6 3\"/>';\n    $('faultChart').innerHTML = s;\n    $('roFaultPts').textContent = det.pts.length + ' 个线像素';\n    $('roThr').textContent = num(faultThr, 2);\n  }\n\n  /* ---------- 屏 3 渲染：后处理矢量化 ---------- */\n  function renderVec() {\n    var vec = M.vectorize(grid1, seg1.seg, segState.rocks, vecState.minArea);\n    var s = '';\n    /* 剔除碎斑后的结果 */\n    for (var y = 0; y < 48; y++) {\n      for (var x = 0; x < 64; x++) {\n        var r = vec.segClean[y * 64 + x];\n        s += '<rect x=\"' + (x * 8) + '\" y=\"' + (y * 8) + '\" width=\"8\" height=\"8\" fill=\"' + M.ROCK_COLORS[r] + '\"/>';\n      }\n    }\n    /* 保留的连通域边界（描边） */\n    for (var c = 0; c < vec.kept.length; c++) {\n      var comp = vec.kept[c];\n      var minX = 1e9, minY = 1e9, maxX = -1, maxY = -1;\n      for (var pi = 0; pi < comp.pts.length; pi++) {\n        if (comp.pts[pi][0] < minX) minX = comp.pts[pi][0];\n        if (comp.pts[pi][0] > maxX) maxX = comp.pts[pi][0];\n        if (comp.pts[pi][1] < minY) minY = comp.pts[pi][1];\n        if (comp.pts[pi][1] > maxY) maxY = comp.pts[pi][1];\n      }\n      s += '<rect x=\"' + (minX * 8) + '\" y=\"' + (minY * 8) + '\" width=\"' + ((maxX - minX + 1) * 8) + '\" height=\"' + ((maxY - minY + 1) * 8) + '\" fill=\"none\" stroke=\"#b26a39\" stroke-width=\"1.6\"/>';\n    }\n    $('vecChart').innerHTML = s;\n    $('roComps').textContent = vec.kept.length + ' 个面要素';\n    $('roDropped').textContent = (vec.sizes.length - vec.kept.length) + ' 个碎斑剔除';\n  }\n\n  /* ---------- 事件绑定 ---------- */\n  function bind() {\n    var rocksBtns = $('rocksBtns');\n    if (rocksBtns) rocksBtns.addEventListener('click', function (e) {\n      var b = e.target.closest('button'); if (!b) return;\n      segState.rocks = parseInt(b.dataset.rocks, 10);\n      Array.prototype.forEach.call(rocksBtns.querySelectorAll('button'), function (x) { x.classList.toggle('on', x === b); });\n      renderSeg(); renderFault(); renderVec();\n    });\n    var inWeight = $('inWeight');\n    if (inWeight) inWeight.addEventListener('input', function () {\n      segState.weight = parseFloat(inWeight.value);\n      $('outWeight').textContent = num(segState.weight, 2);\n      renderSeg(); renderFault(); renderVec();\n    });\n    var inThr = $('inThr');\n    if (inThr) inThr.addEventListener('input', function () {\n      faultThr = parseFloat(inThr.value);\n      renderFault();\n    });\n    var inMin = $('inMinArea');\n    if (inMin) inMin.addEventListener('input', function () {\n      vecState.minArea = parseInt(inMin.value, 10);\n      $('outMinArea').textContent = vecState.minArea;\n      renderVec();\n    });\n  }\n\n  /* 抽屉上报（嵌入主站时按段落显示控件） */\n  function setupDrawer() {\n    if (window.parent === window) return;\n    var secs = [];\n    [['sec1', '语义分割', 'segCtl'], ['sec2', '构造线提取', 'faultCtl'], ['sec3', '矢量化', 'vecCtl']].forEach(function (s) {\n      var el = $(s[2]); if (!el) return;\n      el.querySelectorAll('input, button').forEach(function (c) {\n        if (c.type === 'range') c.setAttribute('value', c.value);\n      });\n      secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n    });\n    try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n    window.addEventListener('message', function (e) {\n      if (e.source !== window.parent) return;\n      var d = e.data;\n      if (!d || d.__drawer !== 'control') return;\n      var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n      if (!el) return;\n      if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      else if (el.tagName === 'BUTTON') { el.click(); }\n    });\n  }\n\n  /* ---------- 启动 ---------- */\n  bind();\n  renderSeg(); renderFault(); renderVec();\n  setupDrawer();\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   地质剖面遥感解译 · 算法解剖（逐像素语义分割 + 构造线提取）\n   ---------------------------------------------------------\n   把「影像 → 矢量图层」拆成 6 步，每一步都跑真代码：\n\n     ① 岩性栅格       合成影像：岩性体 + 噪声 + 断层带\n     ② 弱标签/强标签   历史图件弱标签 vs 精修掩膜强标签\n     ③ 语义分割       编码器-解码器逐像素预测类别\n     ④ 类别概率       概率图 + argmax → 岩性分布\n     ⑤ 构造线提取     梯度 + 阈值 → 线状构造要素\n     ⑥ 矢量化后处理   连通域 + 剔碎斑 + 边界平滑 → 矢量图层\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function ease(t) { return t * t * (3 - 2 * t); }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  /* 面板底部小结框 */\n  function footBox(x, w, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  /* 小格着色图：把 label 数组画成色块（cell 像素边长） */\n  function rockMap(label, W, H, cell, colors, x0, y0, w, h) {\n    var s = '';\n    for (var y = 0; y < H; y++) {\n      for (var x = 0; x < W; x++) {\n        var r = label[y * W + x];\n        s += G.rect(x0 + x * cell, y0 + y * cell, cell, cell, { fill: colors[r], op: 1 });\n      }\n    }\n    return s;\n  }\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.rocks, L.weight, L.noise, L.thr, L.minArea].join(',');\n    if (cache.key === key) return cache;\n    var grid = M.genRockGrid(64, 48, L.rocks, 20261102);\n    var seg = M.semanticSeg(grid, L.rocks, L.weight, L.noise);\n    var ev = M.segEval(grid, seg.seg, L.rocks);\n    var det = M.detectFault(grid, L.thr);\n    var vec = M.vectorize(grid, seg.seg, L.rocks, L.minArea);\n    cache = { key: key, L: L, grid: grid, seg: seg, ev: ev, det: det, vec: vec };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 岩性栅格\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), grid = c.grid, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 合成影像', '岩性体 + 噪声 + 断层带', C.jade);\n    s += G.panel(1, '② 真值标签', '模拟人工精修掩膜', C.blue);\n    s += G.panel(2, '③ 这条影像', '岩性+构造都在像素里', C.clay);\n\n    var cell = 4, x0 = 30, y0 = 130;\n    /* 真值栅格（区域显示） */\n    s += rockMap(grid.label, 64, 48, cell, M.ROCK_COLORS, x0, y0, 256, 192);\n    /* 断层参考线 */\n    s += G.line(x0 + grid.fault.x1 * cell, y0 + grid.fault.y1 * cell, x0 + grid.fault.x2 * cell, y0 + grid.fault.y2 * cell, { stroke: '#2f7d6b', sw: 2, dash: '6 3' });\n    s += G.txt(x0, y0 - 12, '岩性标签图 · ' + L.rocks + ' 类', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    /* 右侧说明 */\n    var names = '';\n    for (var r = 1; r < Math.min(L.rocks, 9); r++) {\n      names += '<rect fill=\"' + M.ROCK_COLORS[r] + '\"/>';\n    }\n    s += footBox(320, 270, 130, 192, '这张影像里有什么',\n      ['· ' + L.rocks + ' 类岩性体随机分布（椭圆近似）',\n       '· 一条斜向断层带贯穿（构造线）',\n       '· 每像素带一个置信度 conf',\n       '',\n       '地质标签稀缺，全靠历史图件',\n       '转弱标签 + 少量精修掩膜。'], 'jade');\n\n    s += G.txt(30, y0 + 208, '人工解译：一幅 1:5 万图幅要 1—2 周 · 换成人机协同：整幅压到小时级', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '岩性类别', v: L.rocks + ' 类' }, { k: '断层带', v: '1 条' }, { k: '栅格', v: '64×48' }], note: '第一步先把地下\"看清楚\"——影像里既有岩性分布，也有构造线索，全部藏在像素里。' };\n  }\n\n  /* =========================================================\n     ② 弱标签 vs 强标签\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), grid = c.grid, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 历史图件（弱标签）', '量大但粗糙', C.clay);\n    s += G.panel(1, '② 精修掩膜（强标签）', '少量但精准', C.jade);\n    s += G.panel(2, '③ 混合训练', '取长补短', C.blue);\n\n    var cell = 4, x0 = 30, y0 = 130;\n    /* 弱标签：粗糙（用 conf 抖动 + 边界模糊模拟） */\n    var weak = new Int32Array(64 * 48);\n    var wrnd = M.mulberry32(20261105);\n    for (var y = 0; y < 48; y++) {\n      for (var x = 0; x < 64; x++) {\n        var idx = y * 64 + x;\n        weak[idx] = grid.label[idx];\n        /* 边界处弱标签容易错（模拟历史图件粗糙） */\n        if (grid.conf[idx] < 0.55 && wrnd() < 0.25) weak[idx] = 0;\n      }\n    }\n    s += rockMap(weak, 64, 48, cell, M.ROCK_COLORS, x0, y0, 256, 192);\n    s += G.txt(x0, y0 - 12, '历史图件弱标签（粗糙）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    /* 强标签：真值 */\n    var x1 = 330, y1 = 130;\n    s += rockMap(grid.label, 64, 48, cell, M.ROCK_COLORS, x1, y1, 256, 192);\n    s += G.txt(x1, y1 - 12, '精修掩膜强标签（精准）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(30, 570, 130, 128, '为什么弱标签能用',\n      ['· 历史地质图已矢量化，投影即标签',\n       '· 量大（覆盖全图幅）但边界粗糙',\n       '· 强标签少量（≥20 幅）拉精度上限',\n       '· 弱强混合，缓解「标签稀缺」'], 'clay');\n\n    s += G.txt(30, y0 + 208, '直接只用弱标签：模型学会「粗糙边界」；必须搭配强标签校准', { size: 9, fill: '#8a4f27' });\n    return { svg: s, stats: [{ k: '弱标签', v: '全图幅' }, { k: '强标签', v: '≥20 幅' }, { k: '策略', v: '混合' }], note: '历史图件转弱标签解决\"量\"，精修掩膜解决\"准\"，两者搭配才能训练出像样的分割模型。' };\n  }\n\n  /* =========================================================\n     ③ 语义分割\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), seg = c.seg, grid = c.grid, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 编码器', '下采样提特征', C.blue);\n    s += G.panel(1, '② 解码器', '上采样回原分辨率', C.jade);\n    s += G.panel(2, '③ 逐像素分类', '每像素取 argmax', C.clay);\n\n    var x0 = 30, y0 = 130, w = 540, h = 130;\n    s += G.axes(x0, y0, w, h, { nx: 4, ny: 2 });\n    /* 模拟 U-Net 收缩-扩张结构：两条对向路径 */\n    var steps = Math.floor(t * 5);\n    var cx = x0 + 40, cy = y0 + 80;\n    var levelW = [110, 86, 62, 42, 62, 86, 110];\n    var levelY = [y0 + 18, y0 + 42, y0 + 58, y0 + 66, y0 + 58, y0 + 42, y0 + 18];\n    for (var i = 0; i <= steps && i < 7; i++) {\n      var filled = (i === steps);\n      var lx = x0 + 30 + i * 74;\n      s += G.rect(lx, levelY[i], levelW[i], 40, { r: 6, fill: filled ? (i < 3 ? C.blueL : C.jadeL) : '#f4f3ef', stroke: i < 3 ? '#9fb5cf' : '#a7c6b8' });\n      s += G.txt(lx + levelW[i] / 2, levelY[i] + 24, i < 3 ? '↓ 下采样' : '↑ 上采样', { size: 8, fill: C.ink3, anchor: 'middle' });\n    }\n    s += G.txt(x0, y0 - 12, 'U-Net 编码器-解码器：收缩提取语义，扩张还原细节', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    /* 右：结果缩略 */\n    var cell = 3, rx = 30 + 200, ry = y0 + 140;\n    /* 原图 */\n    s += rockMap(grid.label, 64, 48, 1, M.ROCK_COLORS, rx, ry, 64, 48);\n    s += G.txt(rx, ry - 8, '真值', { size: 8.5, fill: C.ink3, anchor: 'middle' });\n    s += G.txt(rx + 90, ry - 8, '预测', { size: 8.5, fill: C.ink3, anchor: 'middle' });\n    s += rockMap(seg.seg, 64, 48, 1, M.ROCK_COLORS, rx + 90, ry, 64, 48);\n\n    var ev = c.ev;\n    s += G.txt(rx, ry + 60, '整体准确率 ' + f(ev.acc * 100, 1) + '%', { size: 9.5, fill: C.jadeD, weight: 700 });\n    s += G.txt(rx, ry + 76, '背景/常见岩性偏高 · 稀有岩性偏低', { size: 8.5, fill: C.ink3 });\n\n    return { svg: s, stats: [{ k: '整体准确率', v: f(ev.acc * 100, 1) + '%' }, { k: '类别数', v: L.rocks + ' 类' }], note: '语义分割为每个像素预测一个岩性类别。类别不均衡下，模型天然偏向背景与常见岩性，需要焦点损失来压住稀有类。' };\n  }\n\n  /* =========================================================\n     ④ 类别概率\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), seg = c.seg, grid = c.grid, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 概率图', '每像素一组概率', C.jade);\n    s += G.panel(1, '② argmax', '取最大概率类别', C.blue);\n    s += G.panel(2, '③ 置信度', '概率越高越可信', C.clay);\n\n    var x0 = 30, y0 = 130;\n    /* 概率热图：选中第 2 类（砂岩）的概率 */\n    var target = 2;\n    var cell = 4;\n    var sHeat = '';\n    for (var y = 0; y < 48; y++) {\n      for (var x = 0; x < 64; x++) {\n        var idx = y * 64 + x;\n        var p = seg.prob[idx * L.rocks + (target % L.rocks)];\n        var g = Math.round(255 * p);\n        sHeat += G.rect(x0 + x * cell, y0 + y * cell, cell, cell, { fill: 'rgb(' + g + ',' + Math.round(255 - g) + ',' + 130 + ')', op: 1 });\n      }\n    }\n    s += sHeat;\n    s += G.txt(x0, y0 - 12, '第 ' + (target % L.rocks) + ' 类（' + M.ROCK_NAMES[target % L.rocks] + '）的概率图', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(320, 270, 130, 192, '概率图怎么读',\n      ['· 每个像素有一组概率（和为 1）',\n       '· 高亮 = 模型很确定是这类',\n       '· 边界处概率低（拿不准）',\n       '· argmax 取最大者作最终类别',\n       '',\n       '边界像素是构造线提取的线索：',\n       '岩性切换处概率快速跳变。'], 'jade');\n\n    s += G.txt(x0, y0 + 208, '概率图同时是「置信度图」：低置信像素交给解释员复核', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '概率维度', v: L.rocks + ' 类' }, { k: '输出', v: '概率图' }], note: '分割的原始输出是一组概率而非单一标签。概率越高越可信，边界处概率模糊——这既是风险点，也是构造线提取的起点。' };\n  }\n\n  /* =========================================================\n     ⑤ 构造线提取\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), det = c.det, grid = c.grid, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 梯度响应', '边界/断层处梯度高', C.blue);\n    s += G.panel(1, '② 阈值切割', '>thr 判为构造像素', C.clay);\n    s += G.panel(2, '③ 线要素', '连接成断层/褶皱', C.jade);\n\n    var x0 = 30, y0 = 130, cell = 4;\n    var W = 64, H = 48;\n    /* 梯度热图 */\n    var maxG = 1.2;\n    var sHeat = '';\n    for (var y = 0; y < H; y++) {\n      for (var x = 0; x < W; x++) {\n        var g = det.grad[y * W + x];\n        var t = clamp(g / maxG, 0, 1);\n        var r = Math.round(255 * t), gr = Math.round(255 * (1 - t));\n        sHeat += G.rect(x0 + x * cell, y0 + y * cell, cell, cell, { fill: 'rgb(' + r + ',' + gr + ',150)', op: 1 });\n      }\n    }\n    s += sHeat;\n    /* 检出线像素 */\n    for (var pi = 0; pi < det.pts.length; pi++) {\n      var p = det.pts[pi];\n      s += G.rect(x0 + p.x * cell, y0 + p.y * cell, cell, cell, { fill: '#b05a51', op: 1 });\n    }\n    /* 真实断层线 */\n    s += G.line(x0 + grid.fault.x1 * cell, y0 + grid.fault.y1 * cell, x0 + grid.fault.x2 * cell, y0 + grid.fault.y2 * cell, { stroke: '#2f7d6b', sw: 2, dash: '6 3' });\n    s += G.txt(x0, y0 - 12, '构造线提取 · 梯度阈值 ' + f(L.thr, 2), { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(320, 270, 130, 192, '为什么用梯度',\n      ['· 断层/岩性界线处概率跳变',\n       '→ 梯度幅值高',\n       '· 阈值太高：构造线断断续续',\n       '· 阈值太低：噪声全被当构造',\n       '',\n       '细长低对比的构造线最易漏判，',\n       '需要走向约束 + 形态学连接。'], 'clay');\n\n    s += G.txt(x0, y0 + 208, '检出 ' + det.pts.length + ' 个线像素 · 与真实断层线对比（绿虚线）', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '检出线像素', v: det.pts.length }, { k: '阈值', v: f(L.thr, 2) }], note: '构造线是细长的低对比目标：从概率图算梯度，再阈值切割得到线像素。阈值是检出率与噪声的杠杆，直接拖动画里的滑杆就能体会。' };\n  }\n\n  /* =========================================================\n     ⑥ 矢量化后处理\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), vec = c.vec, seg = c.seg, grid = c.grid, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 连通域', '同一类别连成一片', C.blue);\n    s += G.panel(1, '② 剔碎斑', '小面积合并回背景', C.clay);\n    s += G.panel(2, '③ 矢量图层', '可直接入库 GIS', C.jade);\n\n    var x0 = 30, y0 = 130, cell = 4;\n    /* 剔除碎斑后的结果 */\n    s += rockMap(vec.segClean, 64, 48, cell, M.ROCK_COLORS, x0, y0, 256, 192);\n    /* 面要素外接框 */\n    for (var ci = 0; ci < vec.kept.length; ci++) {\n      var comp = vec.kept[ci];\n      var minX = 1e9, minY = 1e9, maxX = -1, maxY = -1;\n      for (var pi = 0; pi < comp.pts.length; pi++) {\n        if (comp.pts[pi][0] < minX) minX = comp.pts[pi][0];\n        if (comp.pts[pi][0] > maxX) maxX = comp.pts[pi][0];\n        if (comp.pts[pi][1] < minY) minY = comp.pts[pi][1];\n        if (comp.pts[pi][1] > maxY) maxY = comp.pts[pi][1];\n      }\n      s += G.rect(x0 + minX * cell, y0 + minY * cell, (maxX - minX + 1) * cell, (maxY - minY + 1) * cell, { fill: 'none', stroke: '#b26a39', sw: 1.6 });\n    }\n    s += G.txt(x0, y0 - 12, '矢量化后处理 · 保留 ' + vec.kept.length + ' 个面要素', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(320, 270, 130, 192, '为什么要后处理',\n      ['· 分割结果是一堆像素，不成\"要素\"',\n       '· 连通域：同类像素聚成一个个面',\n       '· 剔碎斑：小面积噪声合并回背景',\n       '· 边缘平滑：才能变成可入库的矢量',\n       '',\n       '碎斑不剔除 → 矢量图全是噪声多边形',\n       '过度平滑 → 薄层岩性被合并掉。'], 'clay');\n\n    s += G.txt(x0, y0 + 208, '产出：岩性面要素 + 构造线要素 + 置信度字段 → 直接入库 GIS', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '面要素', v: vec.kept.length }, { k: '剔碎斑', v: (vec.sizes.length - vec.kept.length) }], note: '像素级的分类结果要变成\"能入库的矢量图层\"，必须做连通域、剔碎斑、边界平滑三步后处理——这一步的质量决定成果能不能直接用。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：地质剖面遥感解译<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n/* 右侧控件抽屉（嵌入主站时由父页面接管，这里保留独立样式兜底） */\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 地质勘察 / 遥感地质解译<\/span>\n  <h1>从「目视勾绘 1—2 周」到「逐像素分割 · 小时级出矢量图层」<\/h1>\n  <p class=\"sub\">三个实验：Q1 看懂语义分割、Q2 提取构造线、Q3 后处理成矢量图层。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 语义分割全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「影像 → 黑盒 → 出图」，而是<b>逐段展开<\/b>：岩性栅格 → 弱强标签 → 语义分割 → 概率图 → 构造线 → 矢量化，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 3—5<\/span>\n    <h2>把「影像 → 矢量图层」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。改岩性类别数、分割权重、构造阈值和碎斑面积，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（分割结果、概率图、线要素、矢量图层）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>semanticSeg / detectFault / vectorize<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 3 步用 U-Net 编码器-解码器结构示意「收缩提语义、扩张还原细节」；<b>②<\/b> 第 5 步把梯度热图与阈值切割并排放，看得见「构造线为什么细长低对比、最易漏判」。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 语义分割 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">目视解译 1—2 周/幅；逐像素语义分割把整幅压到小时级<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 3<\/span>\n    <h2>语义分割：每个像素到底属于哪类岩性<\/h2>\n    <p class=\"leadline\">切岩性类别数、拖分割权重，看预测结果与真值的差距——这就是「逐像素判别岩性与构造」的核心。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"segCtl\">\n    <div class=\"btns\" id=\"rocksBtns\">\n      <button type=\"button\" data-rocks=\"3\">3 类<\/button>\n      <button type=\"button\" data-rocks=\"5\" class=\"on\">5 类<\/button>\n      <button type=\"button\" data-rocks=\"7\">7 类<\/button>\n    <\/div>\n    <div class=\"sl\">\n      <label>分割权重<output id=\"outWeight\">0.50<\/output><\/label>\n      <input type=\"range\" id=\"inWeight\" min=\"0\" max=\"1.4\" step=\"0.05\" value=\"0.5\">\n    <\/div>\n  <\/div>\n  <div class=\"legend\" id=\"segLegend\"><\/div>\n  <div class=\"fg\">\n    <div><svg id=\"segTrue\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"真值标签图\"><\/svg><div class=\"cap\">真值（模拟精修掩膜）<\/div><\/div>\n    <div><svg id=\"segPred\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"预测结果\"><\/svg><div class=\"cap\">语义分割预测<\/div><\/div>\n  <\/div>\n  <svg id=\"segProb\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"概率图\" style=\"margin-top:12px\"><\/svg>\n  <div class=\"rrow ro3\">\n    <div class=\"ro\"><span class=\"k\">整体准确率<\/span><b id=\"roAcc\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">各类 IoU<\/span><b id=\"roIou\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"segTip\">拖「分割权重」模拟模型训练充分程度：权重越高，预测越贴近真值，边界越清晰；类别越多，稀有岩性越容易被背景吞掉。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 构造线提取 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>梯度响应<\/b> + <b>阈值切割<\/b> 从概率图里提取断层 / 褶皱线要素<span class=\"qa-algo\">计算机视觉 · 边缘 / 脊线检测<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 4<\/span>\n    <h2>构造线：从像素里把一条断层「捞」出来<\/h2>\n    <p class=\"leadline\">构造线细长、低对比，直接阈值会断断续续。拖阈值在「检出更多」与「噪声更少」之间取平衡。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"faultCtl\">\n    <div class=\"sl\">\n      <label>构造线阈值<output id=\"outThr\">0.60<\/output><\/label>\n      <input type=\"range\" id=\"inThr\" min=\"0.2\" max=\"1.1\" step=\"0.02\" value=\"0.6\">\n    <\/div>\n  <\/div>\n  <svg id=\"faultChart\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"梯度热图与构造线提取\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">检出线像素<\/span><b id=\"roFaultPts\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">阈值<\/span><b id=\"roThr\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"faultTip\">红色 = 检出的构造像素，绿色虚线 = 真实断层参考。阈值低：断层全出来但噪声多；阈值高：干净但构造线断断续续。构造线提取要在「完整」与「干净」间取平衡。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 后处理矢量化 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">分割像素 → 连通域 → 剔碎斑 → 边界平滑 → 可直接入库的矢量图层<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 5<\/span>\n    <h2>矢量化后处理：像素怎么变成「面要素」<\/h2>\n    <p class=\"leadline\">把同一类别的像素聚成连通域，剔除小面积碎斑，得到带边界的面要素——这才是能入库 GIS 的成果。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"vecCtl\">\n    <div class=\"sl\">\n      <label>碎斑面积阈值<output id=\"outMinArea\">18<\/output><\/label>\n      <input type=\"range\" id=\"inMinArea\" min=\"4\" max=\"60\" step=\"1\" value=\"18\">\n    <\/div>\n  <\/div>\n  <svg id=\"vecChart\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"矢量化后处理结果\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">保留面要素<\/span><b id=\"roComps\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">剔除碎斑<\/span><b id=\"roDropped\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"vecTip\">橙色边框 = 保留下来的岩性面要素。碎斑阈值太小：小噪声块也被保留；太大：有价值的薄层岩性被合并掉。后处理的质量决定成果能不能直接入库。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 3<\/b><br>逐像素语义分割，每个像素判一个岩性类别。<\/div>\n    <div><b>实验 2 → STEP 4<\/b><br>梯度 + 阈值，从概率图里提取构造线要素。<\/div>\n    <div><b>实验 3 → STEP 5<\/b><br>连通域 + 剔碎斑 + 平滑 → 矢量图层。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：岩性栅格由「岩性体 + 噪声 + 断层带」合成，真值标签已知、仅供对比；语义分割、构造线提取与矢量化均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：一张影像怎么一步步变成矢量图层',\n    stages: [\n      { name: '岩性栅格', tag: '合成影像', dur: 4200, draw: function (t, g) { return F.stage1(t); } },\n      { name: '弱强标签', tag: '量 + 准', dur: 4400, draw: function (t, g) { return F.stage2(t); } },\n      { name: '语义分割', tag: '编码器-解码器', dur: 4800, draw: function (t, g) { return F.stage3(t); } },\n      { name: '类别概率', tag: '概率图 + argmax', dur: 4400, draw: function (t, g) { return F.stage4(t); } },\n      { name: '构造线提取', tag: '梯度 + 阈值', dur: 4600, draw: function (t, g) { return F.stage5(t); } },\n      { name: '矢量化', tag: '连通域 + 剔碎斑', dur: 4600, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的岩性栅格演示逐像素语义分割、构造线提取与矢量化后处理。","height":600};
  var META = {"id":"g1-remote-seg","sceneId":"g1","title":"地质剖面遥感解译：逐像素语义分割与构造线提取"};
  var handle = null;
  var DEF = {"id":"g1-remote-seg","sceneId":"g1","title":"地质剖面遥感解译：逐像素语义分割与构造线提取","methods":["cv"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"多光谱影像","desc":"单幅千万像素级，覆盖整个图幅"},{"label":"标注成本","value":"高","desc":"岩性标签稀缺，历史图件可作弱标签"},{"label":"可见收益","value":"1—2 周 → 小时级","desc":"整幅解译时间大幅压缩"},{"label":"难度","value":"中","desc":"公开影像充足，但地质标签稀缺、跨气候区迁移差"}],"lede":"遥感影像是区域地质调查的第一手资料——多光谱、高光谱与 SAR 影像记录了地表岩性、构造与蚀变的差异，解释员据此勾绘岩性界线、断层与褶皱。智能方法把「目视勾绘」升级为「逐像素语义分割」：算法把影像里的每个像素判别成某类岩性或构造，再后处理成可直接入库的矢量图层，替代人工勾绘。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>区域地质调查的第一步是把地表<b>「看清楚」<\/b>：解释员对着多光谱 / 高光谱 / SAR 影像，凭色调、纹理、地形和蚀变特征勾绘岩性界线、断层、褶皱与蚀变带，形成一幅幅地质图。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>慢<\/b>——一幅 1:5 万图幅的目视解译需 <b>1—2 周<\/b>，历史图件数以万计<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>不一致<\/b>——同一影像不同解释员勾绘的界线可相差 <b>上百米<\/b><\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>易漏判<\/b>——植被、风化层覆盖区信噪比低，构造线与薄层岩性容易被忽略<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"目视解译的慢、不一致与漏判\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">目视解译：慢 · 不一致 · 易漏判<\/text><rect x=\"20\" y=\"36\" width=\"186\" height=\"176\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"113\" y=\"58\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">一张影像 × 两个人<\/text><rect x=\"36\" y=\"70\" width=\"60\" height=\"90\" rx=\"4\" fill=\"#efe9d8\" stroke=\"#c9bf9d\" stroke-dasharray=\"4 2\"/><rect x=\"96\" y=\"70\" width=\"94\" height=\"90\" rx=\"4\" fill=\"#dce6d6\" stroke=\"#9fb58f\" stroke-dasharray=\"4 2\"/><path d=\"M36 70 C80 90 70 120 96 160\" fill=\"none\" stroke=\"#b26a39\" stroke-width=\"2\" stroke-dasharray=\"5 3\"/><text x=\"113\" y=\"178\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a6b52\">界线 A<\/text><rect x=\"36\" y=\"196\" width=\"60\" height=\"6\" rx=\"3\" fill=\"#efe9d8\"/><rect x=\"96\" y=\"196\" width=\"94\" height=\"6\" rx=\"3\" fill=\"#dce6d6\"/><text x=\"233\" y=\"66\" font-size=\"10\" fill=\"#4d565b\">两人界线差可<\/text><text x=\"233\" y=\"80\" font-size=\"13\" fill=\"#b26a39\" font-weight=\"700\">上百米<\/text><text x=\"233\" y=\"98\" font-size=\"9.5\" fill=\"#79828a\">对同一图幅<\/text><text x=\"233\" y=\"150\" font-size=\"10\" fill=\"#4d565b\">一幅 1:5 万图幅<\/text><text x=\"233\" y=\"164\" font-size=\"10\" fill=\"#4d565b\">目视解译需<\/text><text x=\"233\" y=\"178\" font-size=\"13\" fill=\"#b26a39\" font-weight=\"700\">1—2 周<\/text><text x=\"233\" y=\"198\" font-size=\"9.5\" fill=\"#79828a\">历史图件数以万计<\/text><path d=\"M222 126 C232 130 240 138 246 150\" fill=\"none\" stroke=\"#9ba3a9\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/><rect x=\"270\" y=\"36\" width=\"330\" height=\"176\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"435\" y=\"58\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">植被 / 风化层覆盖区：信噪比低<\/text><path d=\"M300 150 C320 138 340 148 360 140 C380 132 400 144 420 138\" fill=\"none\" stroke=\"#5a8a5a\" stroke-width=\"3\" opacity=\"0.7\"/><path d=\"M310 168 C330 158 350 166 370 158\" fill=\"none\" stroke=\"#5a8a5a\" stroke-width=\"2.5\" opacity=\"0.6\"/><text x=\"300\" y=\"130\" font-size=\"9\" fill=\"#5a8a5a\">植被覆盖<\/text><rect x=\"440\" y=\"120\" width=\"140\" height=\"70\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#d8a48c\" stroke-dasharray=\"5 3\"/><text x=\"510\" y=\"142\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">断层线（易漏判）<\/text><text x=\"510\" y=\"158\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a6b52\">被植被/风化掩盖<\/text><text x=\"510\" y=\"172\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a6b52\">人工难以分辨<\/text><text x=\"300\" y=\"206\" font-size=\"8.5\" fill=\"#8a6b52\">构造线与薄层岩性最容易被忽略<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>把「目视勾绘」换成「<b>逐像素语义分割<\/b>」：算法为影像里每个像素预测一个类别（岩性 / 构造 / 背景），再后处理成<b>可直接入库的矢量图层<\/b>，解释员只负责抽查复核与局部修正。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>语义分割<\/b>——U-Net / DeepLab 逐像素判别岩性（灰岩、砂岩、泥岩、火山岩…）与构造线，输出<b>类别概率图<\/b><\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>构造线提取<\/b>——从分割结果里检测断层、褶皱与蚀变带，用边缘 / 脊线方法生成线状要素<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>弱监督增强<\/b>——历史地质图转成弱标签，与少量人工精修掩膜一起训练，缓解标签稀缺<\/span><\/div><\/div><p>落地形态：整幅解译从 1—2 周压到小时级；算法输出统一尺度的矢量图层，解释员把精力集中在争议区与重点构造上。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"逐像素语义分割流程\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">逐像素语义分割：影像 → 类别概率 → 矢量图层<\/text><rect x=\"20\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"80\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">多光谱影像<\/text><rect x=\"32\" y=\"72\" width=\"36\" height=\"36\" rx=\"3\" fill=\"#8aa77f\"/><rect x=\"70\" y=\"72\" width=\"36\" height=\"36\" rx=\"3\" fill=\"#cbbf9a\"/><rect x=\"32\" y=\"110\" width=\"36\" height=\"36\" rx=\"3\" fill=\"#9b86a8\"/><rect x=\"70\" y=\"110\" width=\"36\" height=\"36\" rx=\"3\" fill=\"#a8bfd4\"/><text x=\"80\" y=\"178\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">RGB 组合显示<\/text><path d=\"M144 100 L168 100\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"172\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"237\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">语义分割模型<\/text><text x=\"237\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">U-Net / DeepLab<\/text><text x=\"237\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">逐像素预测类别<\/text><text x=\"237\" y=\"114\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">输出概率图<\/text><text x=\"237\" y=\"134\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">岩性 + 构造 + 背景<\/text><text x=\"237\" y=\"150\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">弱监督 + 精修掩膜<\/text><path d=\"M306 100 L330 100\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"334\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"394\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">后处理矢量化<\/text><text x=\"394\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">连通域 + 边缘平滑<\/text><text x=\"394\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">构造线骨架化<\/text><text x=\"394\" y=\"118\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">输出矢量图层<\/text><text x=\"394\" y=\"138\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">可直接入库 GIS<\/text><path d=\"M458 100 L482 100\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"486\" y=\"40\" width=\"114\" height=\"120\" rx=\"6\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"543\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">解释员复核<\/text><text x=\"543\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">抽查 + 局部修正<\/text><text x=\"543\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">争议区重点复查<\/text><text x=\"543\" y=\"118\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">确认后入库<\/text><text x=\"310\" y=\"210\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">产出统一尺度、可直接入库的矢量图层<\/text><text x=\"310\" y=\"226\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">人不再逐像素勾绘，只处理算法拿不准的地方<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>多光谱 / 高光谱影像<\/b>：单幅千万像素级、覆盖整个图幅，是分割的主信号（Sentinel-2 / Landsat-8 等公开影像即可起步）；<b>历史地质图<\/b>：与影像同区域、已矢量化，可直接投影转为<b>弱标签<\/b>，弥补标注稀缺；<b>人工精修岩性掩膜<\/b>：≥ 20 幅高质量掩膜，作为强标签与验证集；<b>DEM 高程与坡度<\/b>：与影像同分辨率，作为辅助通道增强判别。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">四类数据 + 标签策略<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">多光谱 / 高光谱影像<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">单幅千万像素级 · 覆盖整个图幅 · 主信号<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">Sentinel-2 / Landsat-8 公开影像即可起步<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#b26a39\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">历史地质图（弱标签）<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">同区域已矢量 · 直接投影转训练标签<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">量大但粗糙，需与精修掩膜搭配<\/text><rect x=\"20\" y=\"106\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">人工精修岩性掩膜<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">≥ 20 幅高质量 · 强标签 + 验证集<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">决定模型精度的上限<\/text><rect x=\"318\" y=\"106\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"330\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">DEM 高程与坡度<\/text><text x=\"330\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">与影像同分辨率 · 辅助通道<\/text><text x=\"330\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">帮助判别地形相关的岩性界线<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"32\" y=\"202\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">标签策略：历史图件弱标签（量大）+ 精修掩膜强标签（精）→ 缓解「地质标签稀缺」<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>地质标签稀缺<\/b>——像素级岩性标注昂贵，历史图件虽是弱标签但与影像不完全对齐<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>类别不均衡<\/b>——背景 / 常见岩性占比极高，稀有岩性与构造线难学<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>跨气候区迁移差<\/b>——同一岩性在不同植被、风化、光照下光谱差异大，换区容易掉精度<\/span><\/div><\/div><p>改进路线按成本从低到高：先用<b>公开影像 + 历史图件弱标签<\/b>把基线做出来；再加<b>类别加权 / 焦点损失<\/b>缓解不均衡；最后做<b>跨区微调<\/b>与<b>解释员在环<\/b>，用少量新区精修掩膜持续校准。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 标签稀缺<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">像素标注昂贵 · 历史图件弱标签<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">弱监督 + 少量精修掩膜<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">历史图件投影转标签做基线<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 类别不均衡<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">背景 / 常见岩性占比极高<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">类别加权 / 焦点损失<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">稀有岩性与构造线单独加权<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 跨区迁移差<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">光照 / 植被 / 风化导致光谱漂移<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">跨区微调 + 解释员在环<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">新区少量掩膜持续校准<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">弱监督基线 → 类别加权 → 跨区微调 + 人在环<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一个图幅的遥感地质解译改造","lead":["某区域地质调查项目，一幅 1:5 万图幅此前目视解译需 1—2 周、两人勾绘界线可差上百米。目标：用语义分割把整幅解译压到小时级，输出统一尺度的矢量图层，界线偏差控制在可复核范围。","注意第 3、4、5 步：语义分割、构造线提取、后处理矢量化是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["图幅","1:5 万"],["影像波段","12 波段"],["岩性类别","8 类"],["精修掩膜","24 幅"],["目标时间","小时级"],["界线偏差","≤50 m"]],"steps":[{"name":"影像接入与预处理","role":"数据","do":"多光谱 / 高光谱影像做辐射定标、大气校正、地理配准；多波段组合选择；与 DEM 对齐到同一栅格。示范页屏 1 可切换不同波段组合看岩性对比度差异。","effect":"一张与历史图件、DEM 严格对齐的影像栅格，作为分割输入。","trap":"地理配准偏差会把影像与标签错开，模型学到的是「错位」而非「岩性」。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">影像接入：定标 → 配准 → 多波段组合<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"44\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">原始影像<\/text><text x=\"99\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">辐射定标·大气校正<\/text><path d=\"M178 64 L202 64\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"44\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"281\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">地理配准<\/text><text x=\"281\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">与图件/DEM对齐<\/text><path d=\"M360 64 L384 64\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"200\" height=\"44\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"488\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">多波段组合<\/text><text x=\"488\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">增强岩性对比度<\/text><text x=\"24\" y=\"112\" font-size=\"9\" fill=\"#79828a\">· 12 波段可选 · 不同组合突出不同岩性/蚀变 · 与 DEM 同栅格<\/text><text x=\"24\" y=\"130\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：配准偏差 → 标签错位 → 学到「错位」而非「岩性」<\/text><\/svg>"},{"name":"弱标签与强标签构建","role":"标注","do":"历史地质图矢量化图层按岩性语义投影转成分割标签（弱）；另精修 ≥20 幅高质量岩性掩膜（强）。按图幅切块、留出独立验证集。示范页屏 1 顶部可对比弱标签与强标签的差异。","effect":"有可训练、可复现评测的像素级标签集，弥补「地质标签稀缺」。","trap":"弱标签与影像不完全对齐、类别粗糙，直接用会把噪声学进模型。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">标签构建：历史图件弱标签 + 精修掩膜强标签<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">历史地质图（弱）<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">投影转标签 · 量大粗糙<\/text><path d=\"M188 68 L210 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">精修岩性掩膜（强）<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">≥20 幅 · 决定精度上限<\/text><path d=\"M378 68 L400 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">切块 + 独立验证集<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">按图幅留出评测口径<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：弱标签类别粗糙且不对齐 → 把噪声学进模型，需与强标签搭配<\/text><\/svg>"},{"name":"语义分割建模","role":"算法核心","do":"用 U-Net / DeepLab 逐像素预测岩性类别概率图；损失用类别加权 / 焦点损失缓解不均衡；弱标签与强标签混合训练。示范页屏 1 在浏览器里实时跑一个小型分割演示。","effect":"输出每像素的类别概率图，直接能看到整幅岩性分布。","trap":"类别不均衡下模型偏向背景 / 常见岩性，稀有岩性与构造线被吞掉。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">语义分割：逐像素预测类别概率<\/text><rect x=\"24\" y=\"42\" width=\"130\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"89\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">影像 Patch<\/text><rect x=\"38\" y=\"72\" width=\"30\" height=\"30\" rx=\"2\" fill=\"#8aa77f\"/><rect x=\"70\" y=\"72\" width=\"30\" height=\"30\" rx=\"2\" fill=\"#cbbf9a\"/><path d=\"M170 77 L200 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"204\" y=\"42\" width=\"130\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"269\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">编码器-解码器<\/text><text x=\"269\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">U-Net / DeepLab<\/text><text x=\"269\" y=\"96\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">焦点损失加权<\/text><path d=\"M338 77 L368 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"372\" y=\"42\" width=\"200\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"472\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">类别概率图<\/text><text x=\"472\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">每像素一组概率<\/text><text x=\"472\" y=\"96\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">取 argmax 得类别<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：类别不均衡 → 模型偏向常见岩性，稀有类被吞掉<\/text><\/svg>"},{"name":"构造线提取","role":"算法核心","do":"从分割结果与梯度图中检测断层、褶皱与蚀变带：边缘检测 + 脊线追踪，得到线状构造要素；按断裂走向与密度统计。示范页屏 2 展示从概率图到线要素的骨架化过程。","effect":"把「一条断层线」从像素里提出来，变成可入库的线状要素。","trap":"构造线细长、对比度低，直接阈值会断断续续，需要形态学连接与走向约束。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">构造线提取：概率图 → 边缘 → 骨架 → 线要素<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">概率图<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">岩性边界处概率跳变<\/text><path d=\"M178 77 L202 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">边缘 / 脊线<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">梯度峰值响应<\/text><path d=\"M360 77 L384 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"463\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">骨架化 + 连接<\/text><text x=\"463\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">走向约束补断点<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：构造线细长低对比 → 阈值法断断续续，需形态学连接 + 走向约束<\/text><\/svg>"},{"name":"后处理与矢量化","role":"工程环节","do":"对分割结果做连通域分析、边缘平滑、碎斑剔除；岩性面要素 + 构造线要素输出为矢量图层（带置信度字段）。示范页屏 3 展示矢量化前后与置信度分层。","effect":"干净、可直接入库 GIS 的矢量成果，而非散乱的像素。","trap":"过度平滑把薄层岩性合并掉；碎斑不剔除会让矢量图全是噪声多边形。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">后处理：连通域 → 平滑 → 剔除碎斑 → 矢量<\/text><rect x=\"24\" y=\"42\" width=\"130\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"89\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">分割掩膜<\/text><text x=\"89\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">含碎斑<\/text><path d=\"M158 77 L182 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"186\" y=\"42\" width=\"130\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"251\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">连通域分析<\/text><text x=\"251\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">剔碎斑<\/text><path d=\"M320 77 L344 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"348\" y=\"42\" width=\"130\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"413\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">边缘平滑<\/text><text x=\"413\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">Douglas 抽稀<\/text><path d=\"M482 77 L506 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"510\" y=\"42\" width=\"86\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"553\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">矢量图层<\/text><text x=\"553\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">带置信度<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：过度平滑合并薄层；碎斑不剔除 → 矢量图全是噪声多边形<\/text><\/svg>"},{"name":"人工复核与入库","role":"人工确认","do":"解释员对置信度低、争议区与重点构造抽查复核，局部修正后确认入库；错误反馈回训练集。示范页屏 3 展示按置信度分层的复核清单。","effect":"人只处理算法拿不准的地方，成果可信、可追溯，错误持续回流改进模型。","trap":"没有人在环，算法错判直接入库，错误会在下游地图里扩散。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">人工复核：按置信度分层 → 局部修正 → 回流<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">置信度分层<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">高置信自动通过<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">人工复核修正<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">争议区·重点构造<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">确认入库 + 回流<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">错误反馈回训练集<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：无人在环 → 算法错判直接入库 → 错误在地图里扩散<\/text><\/svg>"}],"metrics":{"title":"怎么算「解译对了」","html":"<p>像素级语义分割用 <b>IoU（交并比）<\/b> 与 <b>边界偏差<\/b> 双重验收：IoU 反映区域命中，边界偏差（预测界线到真值界线的最短距离）反映勾绘精度——<b>像素 IoU 高但边界漂移上百米，对地质图没意义<\/b>。<\/p><p>构造线提取单独算 <b>线检出率<\/b> 与 <b>长度命中比<\/b>；最终还要与人工解译比<b>整幅时间<\/b>。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='语义分割效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>语义分割验收：像素 IoU 与边界偏差并重<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>预测 vs 真值<\/text><rect x='34' y='66' width='70' height='44' rx='4' fill='#cbbf9a' opacity='0.6'/><rect x='84' y='66' width='70' height='44' rx='4' fill='#8aa77f' opacity='0.6'/><path d='M34 66 C50 76 70 86 104 88 C118 88 128 92 154 96' fill='none' stroke='#b26a39' stroke-width='2.5'/><text x='170' y='86' font-size='9' fill='#4d565b'>边界偏差<\/text><text x='170' y='102' font-size='9' fill='#b26a39' font-weight='700'>≤50 m 命中<\/text><text x='170' y='120' font-size='8.5' fill='#79828a'>IoU ≥ 0.65<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>像素 IoU 高但边界漂移上百米 → 对地质图无意义<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>与人工解译比整幅时间<\/text><rect x='340' y='66' width='90' height='52' fill='#d9b78e'/><text x='385' y='96' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>1—2 周<\/text><text x='385' y='112' text-anchor='middle' font-size='8' fill='#8a6b52'>目视解译<\/text><rect x='500' y='66' width='90' height='52' fill='#2f7d6b'/><text x='545' y='96' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>小时级<\/text><text x='545' y='112' text-anchor='middle' font-size='8' fill='#b9d8cb'>AI 分割<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>时间压缩 + 界线一致性统一<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 像素 IoU × 边界偏差 × 整幅时间 · 三项都要达标<\/text><\/svg><\/p>"},"fails":[{"name":"标签错位","why":"影像与历史图件地理配准偏差，弱标签错位，模型学到「错位」而非「岩性」，边界系统性偏移。"},{"name":"类别不均衡吞掉稀有类","why":"背景与常见岩性占比极高，稀有岩性与构造线样本少，模型偏向常见类、吞掉细线构造。"},{"name":"跨区迁移掉精度","why":"光照、植被、风化条件变化导致同一岩性光谱漂移，换一个气候区直接掉精度，需微调与人在环。"},{"name":"过度平滑合并薄层","why":"后处理边缘平滑 / 形态学操作把有价值的薄层岩性合并掉，矢量图丢了细节。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的岩性栅格演示逐像素语义分割、构造线提取与矢量化后处理。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
